function validate([stones]) {
  if (!Array.isArray(stones) || stones.length < 3 || stones.length > 10000) return 'stones needs 3 to 10^4 positions.';
  if (stones.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each position is a whole number from 1 to 10^9.';
  if (new Set(stones).size !== stones.length) return 'All positions must be different.';
  return null;
}

