function numMovesStonesII(stones) {
  // Exhaustive game search over sorted position lists, trying every legal move and caching [fewest, most].
  const n = stones.length;
  const memo = new Map();
  const solve = (state) => {
    const key = state.join(',');
    if (memo.has(key)) return memo.get(key);
    const taken = new Set(state);
    const nextStates = [];
    // The smallest stone must land strictly between the second smallest and the largest.
    for (let p = state[1] + 1; p < state[n - 1]; p++) {
      if (!taken.has(p)) nextStates.push([...state.slice(1), p].sort((a, b) => a - b));
    }
    // The largest stone must land strictly between the smallest and the second largest.
    for (let p = state[0] + 1; p < state[n - 2]; p++) {
      if (!taken.has(p)) nextStates.push([...state.slice(0, n - 1), p].sort((a, b) => a - b));
    }
    let result = [0, 0];
    if (nextStates.length > 0) {
      let low = Infinity, high = -Infinity;
      for (const next of nextStates) {
        const [childLow, childHigh] = solve(next);
        low = Math.min(low, childLow + 1);
        high = Math.max(high, childHigh + 1);
      }
      result = [low, high];
    }
    memo.set(key, result);
    return result;
  };
  return solve([...stones].sort((a, b) => a - b));
}

