function generate(rand, size) {
  const pick = (count, span) => {
    // count distinct values from 1..span, in random order.
    if (span <= 20000) {
      const pool = Array.from({ length: span }, (_, i) => i + 1);
      for (let i = 0; i < count; i++) {
        const j = i + Math.floor(rand() * (span - i));
        [pool[i], pool[j]] = [pool[j], pool[i]];
      }
      return pool.slice(0, count);
    }
    const seen = new Set();
    while (seen.size < count) seen.add(1 + Math.floor(rand() * span));
    return [...seen];
  };
  if (size === 'large') {
    const n = 1500 + Math.floor(rand() * 501);
    const mode = Math.floor(rand() * 3);
    const span = mode === 0 ? 1000000000 : mode === 1 ? n + Math.floor(rand() * 20) : 3 * n;
    const offset = mode === 0 ? 0 : Math.floor(rand() * (1000000000 - span));
    return [pick(n, span).map(v => v + offset)];
  }
  const n = 3 + Math.floor(rand() * 4);
  const span = n + Math.floor(rand() * 7);
  const offset = rand() < 0.2 ? 1000000000 - span : Math.floor(rand() * 20);
  return [pick(n, span).map(v => v + offset)];
}
